-- United States deep-dive content: page, stats, file_format cards,
-- scope_transmission cards + lifecycle card ("DBNAlliance's 4-corner model"),
-- steps, penalties_related cards, 2 portals. No penalty rows/table.
-- Status-banner text folded into scope_intro, per UK/Spain/Ireland precedent.

INSERT OR IGNORE INTO deep_dive_pages (country_id, last_updated) SELECT id, '2026-07-21' FROM countries WHERE name_en = 'United States';
INSERT OR IGNORE INTO deep_dive_page_translations (country_id, lang, compliance_model, footer_disclaimer, timeline_intro, file_format_intro, scope_intro, steps_intro, penalties_intro) SELECT id, 'en', 'Fully voluntary, decentralised 4-corner', 'This deep-dive page reflects publicly available guidance as of July 2026 and is provided for general awareness, not legal or tax advice. The US e-invoicing landscape is entirely market-driven with no mandate on the horizon — confirm current developments directly with DBNAlliance or the Federal Reserve''s payments improvement initiative before making infrastructure decisions.', 'The US approach has been market-led from the start — a payments-efficiency project born out of the Federal Reserve, not a tax authority closing a VAT gap (the US doesn''t have a VAT).', 'There''s no federally mandated format — the DBNAlliance network has its own standard, but plenty of US commerce still runs on decades-old EDI instead.', 'There is no federal B2B e-invoicing mandate in the United States, and none is currently proposed on any fixed timeline. Two genuinely separate channels exist today: the voluntary DBNAlliance network for B2B, and a distinct, existing federal procurement channel (B2G) for anyone selling to the government — both real today, neither compulsory for private B2B trade.', 'Nothing here is mandatory — but given the direction of travel globally, proactive readiness has real upside even without a regulatory deadline forcing it.', 'No penalty framework exists because there''s no mandate to enforce — the entire posture here is structurally different from every clearance-model country in this tracker.' FROM countries WHERE name_en = 'United States';

