INSERT OR IGNORE INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'file_format', 0 FROM countries WHERE name_en = 'United States';
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'en', 'DBNAlliance network format', '[["Base", "UBL-based invoices, Peppol-style"], ["Standards", "Open, non-proprietary"]]', 'The framework deliberately mirrors Peppol''s technical approach — a genuine advantage if your business already has Peppol experience from EU or Australia/NZ operations.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries co ON co.id = dc.country_id WHERE co.name_en = 'United States' AND dc.section = 'file_format' AND dc.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'file_format', 1 FROM countries WHERE name_en = 'United States';
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'en', 'What actually dominates today', '[["Large enterprises", "Widespread legacy EDI, used for decades"], ["Growing alternative", "DBNAlliance network-based exchange"]]', 'Don''t assume "e-invoicing in the US" means DBNAlliance by default — most large-enterprise structured invoicing today still runs on bilateral EDI arrangements, not the newer network.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries co ON co.id = dc.country_id WHERE co.name_en = 'United States' AND dc.section = 'file_format' AND dc.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'file_format', 2 FROM countries WHERE name_en = 'United States';
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'en', 'No mandated content requirements', '[["Federal format mandate", "None, for domestic B2B"], ["IRS involvement", "None — no e-invoicing requirement of any kind"]]', 'This is a genuinely different posture from almost every other country in this tracker — there''s no tax authority driving format standardisation here at all.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries co ON co.id = dc.country_id WHERE co.name_en = 'United States' AND dc.section = 'file_format' AND dc.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'file_format', 3 FROM countries WHERE name_en = 'United States';
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'en', 'Cross-border reality check', '[["If you trade with the EU, Mexico, Brazil, Saudi Arabia, etc.", "You''ll meet their mandates regardless of US rules"]]', 'A US company with meaningful international operations will encounter e-invoicing mandates abroad long before any equivalent exists domestically — plan accordingly rather than treating this as a purely domestic question.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries co ON co.id = dc.country_id WHERE co.name_en = 'United States' AND dc.section = 'file_format' AND dc.sort_order = 3;

INSERT OR IGNORE INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'scope_transmission', 0 FROM countries WHERE name_en = 'United States';
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'en', 'Governance', '[["DBNAlliance", "Nonprofit governing the exchange framework"], ["Origin", "Business Payments Coalition E-Invoice Exchange Market Pilot"], ["Backing", "Developed with Federal Reserve Financial Services support"]]', 'DBNAlliance defines electronic delivery standards, policies, and guidelines, and helps service providers connect to the framework — but it has no regulatory or tax-collection authority whatsoever.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries co ON co.id = dc.country_id WHERE co.name_en = 'United States' AND dc.section = 'scope_transmission' AND dc.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'scope_transmission', 1 FROM countries WHERE name_en = 'United States';
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'en', 'Federal procurement — a separate channel', '[["Platform", "Treasury Bureau of the Fiscal Service''s Invoice Processing Platform (IPP)"], ["Scope", "Federal agency procurement only — not the DBNAlliance network"]]', 'Don''t conflate these — if you sell to a federal agency, you''re dealing with IPP or an agency-approved solution, a completely distinct system from the voluntary B2B DBNAlliance network.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries co ON co.id = dc.country_id WHERE co.name_en = 'United States' AND dc.section = 'scope_transmission' AND dc.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'scope_transmission', 2 FROM countries WHERE name_en = 'United States';
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'en', 'Payment-method agnostic', '[["Supported methods", "ACH, wire, card, instant payments"]]', 'The exchange framework supports all major electronic payment methods — it''s explicitly designed around payment efficiency, reinforcing that this is a payments-industry initiative rather than a tax-compliance one.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries co ON co.id = dc.country_id WHERE co.name_en = 'United States' AND dc.section = 'scope_transmission' AND dc.sort_order = 2;

