INSERT OR IGNORE INTO deep_dive_steps (country_id, sort_order) SELECT id, 0 FROM countries WHERE name_en = 'United States';
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'en', 'If you supply federal agencies, confirm your IPP setup', 'This is the one genuinely existing obligation here — check you''re connected via the Treasury''s Invoice Processing Platform or your agency''s approved alternative.' FROM deep_dive_steps ds JOIN countries co ON co.id = ds.country_id WHERE co.name_en = 'United States' AND ds.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_steps (country_id, sort_order) SELECT id, 1 FROM countries WHERE name_en = 'United States';
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'en', 'Evaluate joining the DBNAlliance network', 'Look for a member service provider or Access Point if you want to modernise B2B invoice exchange with major trading partners — participation is entirely optional.' FROM deep_dive_steps ds JOIN countries co ON co.id = ds.country_id WHERE co.name_en = 'United States' AND ds.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_steps (country_id, sort_order) SELECT id, 2 FROM countries WHERE name_en = 'United States';
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'en', 'Audit your existing EDI relationships', 'If you already exchange structured invoices via bilateral EDI, weigh whether DBNAlliance''s open framework could reduce mapping overhead over time versus maintaining point-to-point connections.' FROM deep_dive_steps ds JOIN countries co ON co.id = ds.country_id WHERE co.name_en = 'United States' AND ds.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_steps (country_id, sort_order) SELECT id, 3 FROM countries WHERE name_en = 'United States';
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'en', 'Confirm your ERP''s UBL capability', 'If you decide to join DBNAlliance, check whether your existing software can generate UBL-based invoices natively, or whether you''ll need an Access Point provider to bridge the gap.' FROM deep_dive_steps ds JOIN countries co ON co.id = ds.country_id WHERE co.name_en = 'United States' AND ds.sort_order = 3;
INSERT OR IGNORE INTO deep_dive_steps (country_id, sort_order) SELECT id, 4 FROM countries WHERE name_en = 'United States';
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'en', 'Build for international mandates regardless of domestic status', 'If you trade with the EU, Mexico, Brazil, Saudi Arabia, or any other mandating country, ensure your systems can produce their required formats — this need exists independently of anything happening in the US.' FROM deep_dive_steps ds JOIN countries co ON co.id = ds.country_id WHERE co.name_en = 'United States' AND ds.sort_order = 4;
INSERT OR IGNORE INTO deep_dive_steps (country_id, sort_order) SELECT id, 5 FROM countries WHERE name_en = 'United States';
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'en', 'Watch your trading partners, not the regulator', 'Network effects — not compliance deadlines — are what will actually drive US e-invoicing adoption forward. If a major customer or supplier asks you to connect via DBNAlliance, that''s the practical trigger to act.' FROM deep_dive_steps ds JOIN countries co ON co.id = ds.country_id WHERE co.name_en = 'United States' AND ds.sort_order = 5;

INSERT OR IGNORE INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'penalties_related', 0 FROM countries WHERE name_en = 'United States';
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'en', '💰 No federal penalties for non-adoption', NULL, NULL, 'This is confirmed repeatedly and unambiguously across sources — there is no regulatory penalty framework for failing to adopt e-invoicing in the US. Any consequences are purely commercial, arising from specific contractual requirements a trading partner or government agency might impose.', NULL, NULL FROM deep_dive_cards dc JOIN countries co ON co.id = dc.country_id WHERE co.name_en = 'United States' AND dc.section = 'penalties_related' AND dc.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'penalties_related', 1 FROM countries WHERE name_en = 'United States';
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'en', '🏦 A payments story, not a tax story', NULL, NULL, 'DBNAlliance''s origin in the Federal Reserve and Business Payments Coalition — rather than the IRS or a state tax authority — is the single most important structural fact about US e-invoicing. The motivation is B2B payment efficiency, not VAT-gap closure (the US has no VAT).', NULL, NULL FROM deep_dive_cards dc JOIN countries co ON co.id = dc.country_id WHERE co.name_en = 'United States' AND dc.section = 'penalties_related' AND dc.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'penalties_related', 2 FROM countries WHERE name_en = 'United States';
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'en', '🇨🇦 A North American, not purely national, network', NULL, NULL, 'DBNAlliance''s framework explicitly covers both the US and Canada — worth knowing if you operate across the border, since the same voluntary network serves both markets.', NULL, NULL FROM deep_dive_cards dc JOIN countries co ON co.id = dc.country_id WHERE co.name_en = 'United States' AND dc.section = 'penalties_related' AND dc.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'penalties_related', 3 FROM countries WHERE name_en = 'United States';
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'en', '🔮 The honest outlook', NULL, NULL, 'Nothing currently in force suggests a US federal mandate is coming on any fixed timeline. That could change — but the safest planning assumption is that structured invoice data is useful regardless of who requires it, not that a domestic deadline is imminent.', NULL, NULL FROM deep_dive_cards dc JOIN countries co ON co.id = dc.country_id WHERE co.name_en = 'United States' AND dc.section = 'penalties_related' AND dc.sort_order = 3;

